from typing import List

class Solution:
    def sumImbalanceNumbers(self, nums: List[int]) -> int:
        n = len(nums)
        total = 0
        for i in range(n):
            sl = []
            gaps = 0
            for j in range(i, n):
                v = nums[j]
                pos = bisect.bisect_left(sl, v)
                if not (pos < len(sl) and sl[pos] == v):
                    # remove old gap between predecessor and successor
                    if 0 < pos < len(sl) and sl[pos] - sl[pos - 1] > 1:
                        gaps -= 1
                    # add new gaps involving v
                    if pos > 0 and v - sl[pos - 1] > 1:
                        gaps += 1
                    if pos < len(sl) and sl[pos] - v > 1:
                        gaps += 1
                    sl.insert(pos, v)
                total += gaps
        return total
